const items = $input.all();
const jobs = [];

for (const item of items) {
  const data = item.json;
  if (!Array.isArray(data)) continue;

  for (const job of data) {
    if (!job || !job.url) continue;
    jobs.push({
      job_title: job.position || '',
      company: job.company || '',
      job_url: job.url.startsWith('http') ? job.url : 'https://remoteok.com' + job.url,
      source: 'RemoteOK',
      location_text: job.location || 'worldwide',
      salary: job.salary || '',
      description: (job.description || '') + ' ' + (job.tags ? job.tags.join(' ') : ''),
      posted_date: job.date || new Date().toISOString(),
      tags: job.tags ? job.tags.join(', ') : ''
    });
  }
}

return jobs.map(j => ({ json: j }));

