const KEYWORDS = [
  'async remote', 'asynchronous remote', 'worldwide remote', 'global remote',
  'work from anywhere', 'remote data analyst', 'remote data scientist',
  'remote ai marketing', 'remote marketing analyst', 'remote growth analyst',
  'remote bi analyst', 'remote automation', 'remote ai workflow',
  'data analyst', 'data scientist', 'business intelligence', 'bi analyst',
  'marketing analyst', 'performance marketing', 'growth analyst',
  'ai marketing', 'ai automation', 'martech'
];

const results = [];
for (const item of $input.all()) {
  const j = item.json;
  const text = [
    j.job_title || '', j.description || '', j.tags || '', j.location_text || ''
  ].join(' ').toLowerCase();

  const matches = KEYWORDS.filter(kw => text.includes(kw));
  if (matches.length > 0) {
    results.push({ json: { ...j, matched_keywords: matches.join(', ') } });
  }
}

return results;

// Get existing URLs from Google Sheets node output
let existingUrls = new Set();
let existingKeys = new Set();

try {
  const sheetsData = $('Get Existing Job URLs').all();
  for (const item of sheetsData) {
    if (item.json.job_url) existingUrls.add(item.json.job_url.trim());
    if (item.json.company && item.json.job_title) {
      existingKeys.add((item.json.company + '|' + item.json.job_title).toLowerCase());
    }
  }
} catch(e) {
  // Sheet may be empty on first run
}

const newJobs = [];
const seenUrls = new Set([...existingUrls]);
const seenKeys = new Set([...existingKeys]);

for (const item of $input.all()) {
  const j = item.json;
  const url = (j.job_url || '').trim();
  const key = ((j.company || '') + '|' + (j.job_title || '')).toLowerCase();

  if (!url) continue;
  if (seenUrls.has(url)) continue;
  if (seenKeys.has(key)) continue;

  seenUrls.add(url);
  seenKeys.add(key);

  const jobId = Buffer.from(url).toString('base64').substring(0, 20);
  newJobs.push({ json: { ...j, job_id: jobId, date_found: new Date().toISOString().split('T')[0] } });
}

return newJobs;

const REJECT_PATTERNS = [
  /\bus only\b/i, /\bunited states only\b/i,
  /\bcanada only\b/i, /\buk only\b/i,
  /\beu only\b/i, /\beurope only\b/i,
  /\beurope-based\b/i, /\beurope only\b/i,
  /\baustralia only\b/i, /\buk[-\s]?based\b/i,
  /\bmust be based in\b/i, /\bmust live in\b/i,
  /\bmust be located in\b/i,
  /\bmust be authorized to work in\b/i,
  /\bauthorized to work in the (us|uk|eu|canada|australia)\b/i,
  /\blocal work permit required\b/i,
  /\bwork permit required\b/i,
  /\bhybrid\b/i,
  /\bonsite\b/i, /\bon-site\b/i,
  /\boffice required\b/i, /\bin-office\b/i,
  /\bremote within .{1,30} only\b/i,
  /\bonly (from|in) (the )?(us|usa|canada|uk|eu|europe|australia)\b/i,
  /\bresidents of\b/i, /\bbased in (the )?(us|usa|uk|eu|europe|canada|australia)\b/i,
  /\bfixed (us|est|pst|cet|bst|gmt)\s+hours\b/i,
  /\bmust work (est|pst|cet|bst)\b/i,
  /\bcore hours.{0,30}(est|pst|cet|bst)\b/i,
  /\bno international\b/i, /\bdomestic only\b/i
];

const KEEP_PATTERNS = [
  /\bworldwide\b/i, /\bworld-wide\b/i,
  /\bglobal remote\b/i, /\bwork from anywhere\b/i,
  /\banywhere\b/i, /\bapac\b/i,
  /\binternational contractor/i, /\bcontractor role\b/i,
  /\bb2b contractor\b/i,
  /\bdeel\b/i, /\bremote\.com\b/i, /\boyster\b/i,
  /\beor\b/i, /\bemployer of record\b/i,
  /\bremote[- ]?first\b/i, /\bdistributed team\b/i,
  /\bopen to international\b/i, /\bfully remote\b/i
];

const results = [];

for (const item of $input.all()) {
  const j = item.json;
  const text = [
    j.job_title || '', j.description || '',
    j.location_text || '', j.tags || ''
  ].join(' ');

  const hasReject = REJECT_PATTERNS.some(p => p.test(text));

  if (hasReject) {
    // Determine reason
    let reason = 'country_restriction';
    if (/hybrid|onsite|on-site|office/i.test(text)) reason = 'hybrid_onsite';
    else if (/fixed.*(us|est|pst|cet|bst)/i.test(text)) reason = 'timezone_risk';

    results.push({ json: { ...j, hard_filter_pass: false, reject_reason: reason } });
  } else {
    results.push({ json: { ...j, hard_filter_pass: true, reject_reason: null } });
  }
}

return results;

const items = $input.all();
const results = [];

for (const item of items) {
  const job = item.json;
  let aiResult = {};

  try {
    // Extract text content from Claude API response
    const content = job.content;
    const text = Array.isArray(content) ? content[0]?.text || '' : '';
    const cleaned = text.replace(/```json\n?/g, '').replace(/```/g, '').trim();
    aiResult = JSON.parse(cleaned);
  } catch(e) {
    aiResult = {
      taiwan_eligible: 'unclear',
      reason: 'AI parse error',
      location_risk: 'medium',
      timezone_risk: 'medium',
      contractor_possible: 'unclear',
      decision: 'manual_check'
    };
  }

  results.push({
    json: {
      ...job,
      taiwan_eligible: aiResult.taiwan_eligible || 'unclear',
      taiwan_reason: aiResult.reason || '',
      location_risk: aiResult.location_risk || 'medium',
      timezone_risk: aiResult.timezone_risk || 'medium',
      contractor_possible: aiResult.contractor_possible || 'unclear',
      ai_decision: aiResult.decision || 'manual_check'
    }
  });
}

return results;

const ASYNC_POSITIVE = [
  /\basync\b/i, /\basynchronous\b/i,
  /\bflexible hours\b/i, /\bflexible schedule\b/i,
  /\bdistributed team\b/i, /\bremote[- ]?first\b/i,
  /\bno meeting\b/i, /\blow meeting\b/i,
  /\bwork across time zones\b/i, /\bown your schedule\b/i,
  /\bwork when you want\b/i, /\byour own hours\b/i
];

const ASYNC_NEGATIVE = [
  /\bstrict 9\s*[–-]\s*5\b/i, /\bfixed us hours\b/i,
  /\bfixed est hours\b/i, /\bfixed pst hours\b/i,
  /\bfixed cet hours\b/i, /\bdaily live calls required\b/i,
  /\bmust overlap.{1,30}full business day\b/i,
  /\bmust be available.{1,30}(9am|9:00).{1,30}(5pm|5:00)/i
];

const results = [];

for (const item of $input.all()) {
  const j = item.json;
  const text = [j.job_title, j.description, j.tags].join(' ');

  const hasNegative = ASYNC_NEGATIVE.some(p => p.test(text));
  if (hasNegative) continue; // skip strictly sync jobs

  let asyncLevel = 'unknown';
  const positiveMatches = ASYNC_POSITIVE.filter(p => p.test(text));
  if (positiveMatches.length >= 3) asyncLevel = 'high';
  else if (positiveMatches.length >= 1) asyncLevel = 'medium';
  else asyncLevel = 'low';

  results.push({ json: { ...j, async_level: asyncLevel } });
}

return results;

const ROLE_TIER1 = [
  /data analyst/i, /data scientist/i, /junior data scientist/i,
  /business intelligence/i, /\bbi analyst\b/i,
  /marketing analyst/i, /performance marketing/i,
  /growth analyst/i, /ai marketing/i,
  /ai automation/i, /automation specialist/i,
  /martech/i, /marketing technology/i,
  /creative strategist/i, /ai workflow/i
];

const ROLE_TIER2 = [
  /analytics/i, /reporting analyst/i,
  /digital marketing/i, /campaign analyst/i,
  /content analyst/i, /seo analyst/i,
  /product analyst/i, /operations analyst/i,
  /revenue analyst/i
];

const results = [];

for (const item of $input.all()) {
  const j = item.json;
  const text = [j.job_title, j.description].join(' ');

  let roleCategory = 'other';
  let roleFitScore = 0;

  if (ROLE_TIER1.some(p => p.test(text))) {
    roleCategory = 'primary';
    roleFitScore = 25;
  } else if (ROLE_TIER2.some(p => p.test(text))) {
    roleCategory = 'adjacent';
    roleFitScore = 15;
  }

  results.push({ json: { ...j, role_category: roleCategory, role_fit_score: roleFitScore } });
}

return results;

const results = [];

for (const item of $input.all()) {
  const j = item.json;
  let score = 0;
  let scoreBreakdown = {};

  // ---- Taiwan Eligibility (max 40 pts) ----
  const desc = [j.description || '', j.location_text || ''].join(' ').toLowerCase();
  let taiwanScore = 0;
  if (
    j.taiwan_eligible === 'yes' ||
    /worldwide|work from anywhere|global remote|contractor/.test(desc)
  ) {
    taiwanScore = 40;
  } else if (/apac/.test(desc)) {
    taiwanScore = 30;
  } else if (j.taiwan_eligible === 'unclear' && j.location_risk !== 'high') {
    taiwanScore = 20;
  } else {
    taiwanScore = 0;
  }
  score += taiwanScore;
  scoreBreakdown.taiwan = taiwanScore;

  // ---- Async Fit (max 25 pts) ----
  let asyncScore = 0;
  if (j.async_level === 'high') asyncScore = 25;
  else if (j.async_level === 'medium') asyncScore = 20;
  else if (/distributed team/i.test(desc)) asyncScore = 15;
  else if (/remote.?first/i.test(desc)) asyncScore = 10;
  score += asyncScore;
  scoreBreakdown.async = asyncScore;

  // ---- Role Fit (max 25 pts) ----
  const roleScore = j.role_fit_score || 0;
  score += roleScore;
  scoreBreakdown.role = roleScore;

  // ---- Salary (max 25 pts) ----
  let salaryScore = 0;
  const salaryText = (j.salary || '').toLowerCase();
  const salaryNum = parseFloat(salaryText.replace(/[^0-9.]/g, ''));

  if (salaryText) {
    salaryScore = 10; // listed at all
    // Very rough monthly equiv detection
    if (
      /5[0-9][0-9][0-9][0-9]|6[0-9][0-9][0-9][0-9]|7[0-9][0-9][0-9][0-9]|8[0-9][0-9][0-9][0-9]|9[0-9][0-9][0-9][0-9]/.test(salaryText) &&
      /year|annual|yr|\/yr/.test(salaryText)
    ) {
      salaryScore = 25; // > $60k/year → > $5k/month
    } else if (
      /3[0-9][0-9][0-9][0-9]|4[0-9][0-9][0-9][0-9]/.test(salaryText) &&
      /year|annual/.test(salaryText)
    ) {
      salaryScore = 15; // > $36k/year → > $3k/month
    } else if (/5000|6000|7000|8000|9000/.test(salaryText) && /month/i.test(salaryText)) {
      salaryScore = 25;
    } else if (/3000|4000/.test(salaryText) && /month/i.test(salaryText)) {
      salaryScore = 15;
    }
  }
  score += salaryScore;
  scoreBreakdown.salary = salaryScore;

  // ---- Why Good Fit (narrative) ----
  const reasons = [];
  if (taiwanScore >= 40) reasons.push('Worldwide/global remote or contractor-friendly');
  else if (taiwanScore >= 30) reasons.push('APAC-friendly');
  if (asyncScore >= 20) reasons.push('Async or flexible hours culture');
  if (roleScore === 25) reasons.push('Strong match for Jerry\'s data/AI/marketing skills');
  if (salaryScore >= 15) reasons.push('Competitive salary listed');
  if (j.contractor_possible === 'yes') reasons.push('Contractor engagement possible');

  results.push({
    json: {
      ...j,
      score,
      score_breakdown: JSON.stringify(scoreBreakdown),
      why_good_fit: reasons.join('; ')
    }
  });
}

return results;

const results = [];

for (const item of $input.all()) {
  const j = item.json;
  let application_status = 'pending';

  const eligible = j.taiwan_eligible === 'yes';
  const highScore = j.score >= 85;
  const medScore = j.score >= 70;
  const asyncGood = j.async_level === 'high' || j.async_level === 'medium';
  const locationSafe = j.location_risk === 'low';
  const timezoneSafe = j.timezone_risk === 'low' || j.timezone_risk === 'medium';

  if (eligible && highScore && asyncGood && locationSafe && timezoneSafe) {
    application_status = 'apply_now';
  } else if ((j.taiwan_eligible === 'unclear') && highScore && j.location_risk === 'medium') {
    application_status = 'manual_check';
  } else if (j.taiwan_eligible === 'no' || j.location_risk === 'high' || j.timezone_risk === 'high') {
    application_status = 'reject';
  } else {
    application_status = 'review';
  }

  results.push({ json: { ...j, application_status } });
}

return results;

const results = [];

for (const item of $input.all()) {
  const j = item.json;
  let coverLetter = '';

  try {
    const content = j.content;
    if (Array.isArray(content) && content[0]?.text) {
      coverLetter = content[0].text;
    }
  } catch(e) {
    coverLetter = 'Cover letter generation failed.';
  }

  results.push({ json: { ...j, cover_letter_draft: coverLetter } });
}

return results;

const jobs = $input.all().map(i => i.json);
const today = new Date().toISOString().split('T')[0];

// Sort by score desc
jobs.sort((a, b) => (Number(b.score) || 0) - (Number(a.score) || 0));

const topJobs = jobs.filter(j => j.taiwan_eligible === 'yes' || j.taiwan_eligible === 'unclear').slice(0, 10);
const manualCheck = jobs.filter(j => j.application_status === 'manual_check').slice(0, 5);

// Count rejections from Rejected sheet
const rejectedUsOnly = jobs.filter(j => j.taiwan_eligible === 'no').length;

let digestHtml = `<h1>Daily Taiwan Eligible Async Remote Jobs – ${today}</h1>`;
digestHtml += `<p>Total new jobs processed today: <strong>${jobs.length}</strong></p>`;
digestHtml += `<hr/>`;
digestHtml += `<h2>Top Jobs Today</h2>`;

topJobs.forEach((job, i) => {
  digestHtml += `
<div style="margin-bottom:24px; border-left:4px solid #0070f3; padding-left:12px;">
  <h3>${i + 1}. ${job.job_title}</h3>
  <p><strong>Company:</strong> ${job.company}</p>
  <p><strong>Score:</strong> ${job.score}/100</p>
  <p><strong>Taiwan Eligible:</strong> ${job.taiwan_eligible}</p>
  <p><strong>Reason:</strong> ${job.taiwan_reason}</p>
  <p><strong>Async Level:</strong> ${job.async_level}</p>
  <p><strong>Timezone Risk:</strong> ${job.timezone_risk}</p>
  <p><strong>Salary:</strong> ${job.salary || 'Not listed'}</p>
  <p><strong>Why it fits Jerry:</strong> ${job.why_good_fit}</p>
  <p><strong>Apply:</strong> <a href="${job.job_url}">${job.job_url}</a></p>
</div>`;
});

if (manualCheck.length > 0) {
  digestHtml += `<hr/><h2>Manual Check Required (High Score, Unclear Eligibility)</h2>`;
  manualCheck.forEach(job => {
    digestHtml += `<p>• <strong>${job.job_title}</strong> at ${job.company} – Score: ${job.score} – <a href="${job.job_url}">Link</a></p>`;
  });
}

digestHtml += `<hr/>
<h2>Rejection Summary</h2>
<ul>
  <li>Taiwan ineligible (AI): ${jobs.filter(j => j.ai_decision === 'reject').length}</li>
  <li>Low score (below 70): ${jobs.filter(j => Number(j.score) < 70).length}</li>
</ul>`;

return [{ json: { digest_html: digestHtml, job_count: topJobs.length, today } }];
